func opts380(q *req, r *reader) (out []p_backoff.ExponentialBackOffOpts, done func(), err error) {
	var dones []func()
	done = func() {
		for _, d := range dones {
			d()
		}
	}
	defer func() {
		if err != nil {
			done()
		}
	}()
	n := r.count()
	if n < 0 {
		return nil, done, nil
	}
	out = make([]p_backoff.ExponentialBackOffOpts, 0, n)
	for range n {
		if r.err != nil {
			break
		}
		switch i := r.u32(); i {
		case 1: // WithInitialInterval
			a0, err := decInt[p_time.Duration](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_backoff.WithInitialInterval(a0))
		case 2: // WithMaxElapsedTime
			a0, err := decInt[p_time.Duration](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_backoff.WithMaxElapsedTime(a0))
		case 3: // WithMaxInterval
			a0, err := decInt[p_time.Duration](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_backoff.WithMaxInterval(a0))
		case 4: // WithMultiplier
			a0, err := decFloat[float64](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_backoff.WithMultiplier(a0))
		case 5: // WithRandomizationFactor
			a0, err := decFloat[float64](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_backoff.WithRandomizationFactor(a0))
		case 6: // WithRetryStopDuration
			a0, err := decInt[p_time.Duration](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_backoff.WithRetryStopDuration(a0))
		default:
			return nil, done, fmt.Errorf("p2p_host: unknown option %d of github.com/cenkalti/backoff/v4.ExponentialBackOffOpts", i)
		}
	}
	return out, done, r.err
}

