func opts764(q *req, r *reader) (out []p_vfs.CloneOption, done func(), err error) {
	var dones []func()
	done = func() {
		for _, d := range dones {
			d()
		}
	}
	defer func() {
		if err != nil {
			done()
		}
	}()
	n := r.count()
	if n < 0 {
		return nil, done, nil
	}
	out = make([]p_vfs.CloneOption, 0, n)
	for range n {
		if r.err != nil {
			break
		}
		switch i := r.u32(); i {
		case 0: // CloneSkip
			var a0 func(string) bool
			if rc := newRetained(q, r.u32()); rc != nil {
				a0 = func(a0 string) bool {
					return rc.ask(func(w *writer) {
						encStr[string](w, a0)
					})
				}
			}
			out = append(out, p_vfs.CloneSkip(a0))
		case 1: // CloneSync
			out = append(out, p_vfs.CloneSync)
		case 2: // CloneTryLink
			out = append(out, p_vfs.CloneTryLink)
		default:
			return nil, done, fmt.Errorf("p2p_host: unknown option %d of github.com/cockroachdb/pebble/v2/vfs.CloneOption", i)
		}
	}
	return out, done, r.err
}

