func opts1855(q *req, r *reader) (out []p_format.BatchOption, done func(), err error) {
	var dones []func()
	done = func() {
		for _, d := range dones {
			d()
		}
	}
	defer func() {
		if err != nil {
			done()
		}
	}()
	n := r.count()
	if n < 0 {
		return nil, done, nil
	}
	out = make([]p_format.BatchOption, 0, n)
	for range n {
		if r.err != nil {
			break
		}
		switch i := r.u32(); i {
		case 0: // MaxNodesBatchOption
			a0, err := decInt[int](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_format.MaxNodesBatchOption(a0))
		case 1: // MaxSizeBatchOption
			a0, err := decInt[int](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_format.MaxSizeBatchOption(a0))
		default:
			return nil, done, fmt.Errorf("p2p_host: unknown option %d of github.com/ipfs/go-ipld-format.BatchOption", i)
		}
	}
	return out, done, r.err
}

