func opts4074(q *req, r *reader) (out []p_stats.Options, done func(), err error) {
	var dones []func()
	done = func() {
		for _, d := range dones {
			d()
		}
	}
	defer func() {
		if err != nil {
			done()
		}
	}()
	n := r.count()
	if n < 0 {
		return nil, done, nil
	}
	out = make([]p_stats.Options, 0, n)
	for range n {
		if r.err != nil {
			break
		}
		switch i := r.u32(); i {
		case 1: // WithMeasurements
			a0, err := dec4072(r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_stats.WithMeasurements(a0...))
		case 2: // WithRecorder
			a0, err := decH[p_stats.Recorder](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_stats.WithRecorder(a0))
		case 3: // WithTags
			a0, err := dec4075(r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_stats.WithTags(a0...))
		default:
			return nil, done, fmt.Errorf("p2p_host: unknown option %d of go.opencensus.io/stats.Options", i)
		}
	}
	return out, done, r.err
}

