func opts4190(q *req, r *reader) (out []p_trace.BatchSpanProcessorOption, done func(), err error) {
	var dones []func()
	done = func() {
		for _, d := range dones {
			d()
		}
	}
	defer func() {
		if err != nil {
			done()
		}
	}()
	n := r.count()
	if n < 0 {
		return nil, done, nil
	}
	out = make([]p_trace.BatchSpanProcessorOption, 0, n)
	for range n {
		if r.err != nil {
			break
		}
		switch i := r.u32(); i {
		case 0: // WithBatchTimeout
			a0, err := decInt[p_time.Duration](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_trace.WithBatchTimeout(a0))
		case 1: // WithBlocking
			out = append(out, p_trace.WithBlocking())
		case 2: // WithExportTimeout
			a0, err := decInt[p_time.Duration](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_trace.WithExportTimeout(a0))
		case 3: // WithMaxExportBatchSize
			a0, err := decInt[int](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_trace.WithMaxExportBatchSize(a0))
		case 4: // WithMaxQueueSize
			a0, err := decInt[int](r)
			if err != nil {
				return nil, done, err
			}
			out = append(out, p_trace.WithMaxQueueSize(a0))
		default:
			return nil, done, fmt.Errorf("p2p_host: unknown option %d of go.opentelemetry.io/otel/sdk/trace.BatchSpanProcessorOption", i)
		}
	}
	return out, done, r.err
}

