func dec5114(r *reader) (v p_unicode.RangeTable, err error) {
	if !r.present() {
		return v, nil
	}
	if v.R16, err = dec5115(r); err != nil {
		return v, err
	}
	if v.R32, err = dec5117(r); err != nil {
		return v, err
	}
	if v.LatinOffset, err = decInt[int](r); err != nil {
		return v, err
	}
	return v, nil
}

func dec5113(r *reader) (*p_unicode.RangeTable, error) {
	if r.absent() {
		return nil, nil
	}
	v, err := dec5114(r)
	return &v, err
}

func dec5112(r *reader) ([]*p_unicode.RangeTable, error) {
	n := r.count()
	if n < 0 {
		return nil, nil
	}
	out := make([]*p_unicode.RangeTable, n)
	for i := range out {
		x, err := dec5113(r)
		if err != nil {
			return nil, err
		}
		out[i] = x
	}
	return out, nil
}

func enc5119(w *writer, v p_event.EvtAutoRelayAddrsUpdated) {
	w.u8(1)
	enc1528(w, v.RelayAddrs)
}

func enc5120(w *writer, v p_event.EvtHostReachableAddrsChanged) {
	w.u8(1)
	enc1528(w, v.Reachable)
	enc1528(w, v.Unreachable)
	enc1528(w, v.Unknown)
}

func enc5123(w *writer, v p_event.UpdatedAddress) {
	w.u8(1)
	encMultiaddr(w, v.Address)
	encInt[p_event.AddrAction](w, v.Action)
}

func enc5122(w *writer, v []p_event.UpdatedAddress) {
	if v == nil {
		w.i32(-1)
		return
	}
	w.i32(int32(len(v)))
	for _, e := range v {
		enc5123(w, e)
	}
}

func enc5121(w *writer, v p_event.EvtLocalAddressesUpdated) {
	w.u8(1)
	encBool[bool](w, v.Diffs)
	enc5122(w, v.Current)
	enc5122(w, v.Removed)
	encH(w, v.SignedPeerRecord)
}

func enc5124(w *writer, v p_event.EvtLocalProtocolsUpdated) {
	w.u8(1)
	enc1980(w, v.Added)
	enc1980(w, v.Removed)
}

